import json
import urllib.request
import xml.etree.ElementTree as ET
from agents import function_tool


def _local(tag):
    return tag.split("}")[-1]


def _parse_entries(xml_bytes):
    root = ET.fromstring(xml_bytes)
    entries = []
    for node in root.iter():
        if _local(node.tag) in ("item", "entry"):
            item = {}
            for child in node:
                name = _local(child.tag)
                if name == "title":
                    item["title"] = (child.text or "").strip()
                elif name == "link":
                    item["link"] = child.attrib.get("href") or (child.text or "").strip()
            entries.append(item)
    return entries


@function_tool
def check_rss_feed_entries(feed_url: str, limit: int = 10) -> str:
    req = urllib.request.Request(feed_url, headers={"User-Agent": "blog-agent/1.0"})
    with urllib.request.urlopen(req, timeout=15) as resp:
        data = resp.read()
    entries = _parse_entries(data)[:limit]
    return json.dumps(entries, indent=2)
